<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import type { TraceProject, StageName, ReportDecision } from '../types';
import { api } from '../api';
import { excludedDocuments, findingLabels, money, reportRows, sourceFor, statusLabels, type ReportSource, type ReportRow } from '../reportView';
import AppIcon from './AppIcon.vue';
import ReportSourceDrawer from './ReportSourceDrawer.vue';
import PdfReportViewer from './PdfReportViewer.vue';
const props = defineProps<{ project: TraceProject; busy: boolean }>();
const emit = defineEmits<{ retry: [stage: StageName]; decision: [decision: ReportDecision] }>();
const selectedSource = ref<ReportSource | null>(null);
const pdfOpen = ref(false);
const filter = ref('problems');
const expanded = ref(new Set<string>());
const comment = ref(''), saving = ref(false), decisionError = ref(''), savedNotice = ref('');
const localDecision = ref<ReportDecision | null>(null);
const rows = computed(() => reportRows(props.project));
const total = computed(() => rows.value.find(r => r.isTotal));
const detailRows = computed(() => rows.value.filter(r => !r.isTotal));
const problems = computed(() => { const items = detailRows.value.filter(r => r.status === 'mismatch'); return !items.length && total.value?.status === 'mismatch' ? [total.value] : items; });
const pending = computed(() => detailRows.value.filter(r => ['insufficient_data', 'needs_review', 'manual_review'].includes(r.status)));
const matched = computed(() => detailRows.value.filter(r => r.status === 'matched'));
const exclusions = computed(() => excludedDocuments(props.project));
const hasResult = computed(() => !!(props.project.financial_audit || props.project.verification_result));
const hasMismatch = computed(() => problems.value.length > 0 || total.value?.status === 'mismatch');
const visible = computed(() => filter.value === 'problems' ? problems.value : filter.value === 'pending' ? pending.value : filter.value === 'matched' ? matched.value : detailRows.value);
const decision = computed(() => localDecision.value || props.project.report_decision);
const filters = computed(() => [{id:'problems', label:'Расхождения', count:problems.value.length}, {id:'pending', label:'Нет подтверждения', count:pending.value.length}, {id:'matched', label:'Совпадает', count:matched.value.length}, {id:'all', label:'Все показатели', count:detailRows.value.length}]);
const heroTitle = computed(() => hasMismatch.value ? 'В отчёте есть расхождение' : pending.value.length ? 'Отчёт проверен частично' : 'Показатели отчёта подтверждены');
const headlineDifference = computed(() => total.value?.status === 'mismatch' ? total.value.difference : problems.value.length === 1 ? problems.value[0]?.difference : null);
const heroText = computed(() => hasMismatch.value ? 'Проверьте отмеченные суммы и подтверждающие документы перед принятием отчёта.' : pending.value.length ? 'Часть показателей совпадает. Для остальных нужны дополнительные документы или проверка специалиста.' : 'Проверенные показатели совпадают с первичными документами. Можно принять решение по отчёту.');
function shortName(name: string) { return name.replace(/^\d+(?:_\d+)?_/, '').replace(/_/g, ' ').replace(/\.[a-z0-9]+$/i, ''); }
function location(source: ReportSource) { const p = source.provenance; return p?.sheet_name ? p.sheet_name + (p.cell_address ? ' · ' + p.cell_address : '') : p?.page_no ? 'Страница ' + p.page_no : 'Фрагмент документа'; }
function open(source?: ReportSource) { if (source?.document_id) selectedSource.value = source; }
function primarySource(document: any) {
  if (document.sources?.[0]) return sourceFor(props.project, document.sources[0]);
  return sourceFor(props.project, { document_id: document.document_id, file_name: document.file_name });
}
function toggle(id: string) { const next = new Set(expanded.value); next.has(id) ? next.delete(id) : next.add(id); expanded.value = next; }
function evidenceOpen(row: ReportRow) { return row.status === 'mismatch' ? !expanded.value.has(row.id) : expanded.value.has(row.id); }
function rowExplanation(row: ReportRow) {
  if (row.status === 'mismatch') {
    const delta = Number(row.difference);
    return Number.isFinite(delta) ? `В отчёте на ${money(Math.abs(delta), row.currency || 'RUB')} ${delta >= 0 ? 'больше' : 'меньше'}, чем подтверждено документами.` : 'Сумма отчёта отличается от суммы подтверждающих документов.';
  }
  if (row.status === 'matched') return 'Сумма совпадает с подтверждающими документами.';
  if (/подколонка|расшифровк/i.test(row.reason)) return 'В комплекте нет отдельной расшифровки для этой части затрат. Подтверждение общей суммы не подтверждает её состав.';
  if (/трудоёмк|трудоемк/i.test(row.title)) return 'Для проверки трудоёмкости нужны табели или расчёты трудозатрат. В загруженном комплекте их недостаточно.';
  return 'По загруженным документам этот показатель пока нельзя подтвердить. Добавьте первичные данные или проверьте его вручную.';
}
function formatDate(value?: string | null) { if (!value) return ''; const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',year:'numeric'}).format(date); }
async function saveDecision(status: 'accepted' | 'rejected') {
  if (saving.value || !props.project.report_fingerprint) return;
  saving.value = true; decisionError.value = ''; savedNotice.value = '';
  try {
    const result = await api.decideReport(props.project.id, { status, comment: comment.value, report_fingerprint: props.project.report_fingerprint });
    localDecision.value = result.report_decision; emit('decision', result.report_decision);
    savedNotice.value = status === 'accepted' ? 'Отчёт принят. Решение сохранено.' : 'Отчёт отклонён. Решение сохранено.';
  } catch (error) { decisionError.value = error instanceof Error ? error.message : 'Не удалось сохранить решение. Попробуйте ещё раз.'; }
  finally { saving.value = false; }
}
watch(() => props.project.id, () => { selectedSource.value = null; localDecision.value = null; expanded.value = new Set(); comment.value = props.project.report_decision?.comment || ''; filter.value = 'problems'; savedNotice.value = ''; decisionError.value = ''; }, { immediate: true });
watch(() => props.project.report_decision, value => { if (value && !saving.value) { localDecision.value = null; comment.value = value.comment; } });
watch(() => props.project.report_fingerprint, () => { localDecision.value = null; savedNotice.value = ''; });
</script>

<template>
  <section class="review-report" aria-label="Отчёт о проверке">
    <header class="report-toolbar"><div><span class="report-overline">Результаты проверки</span><h2>Сверка отчёта</h2></div><div class="report-tools"><button v-if="project.financial_audit" class="review-button secondary" @click="pdfOpen = true"><AppIcon name="result" /> Заключение · PDF</button><button class="review-icon-button" :disabled="busy || project.status === 'running' || !hasResult" aria-label="Повторить сверку" title="Повторить сверку" @click="emit('retry','reconciliation')">↻</button></div></header>
    <template v-if="hasResult">
      <section class="report-verdict" :class="{ 'has-problems': hasMismatch, 'all-clear': !hasMismatch && !pending.length }"><div class="verdict-main"><span class="verdict-status"><span aria-hidden="true">{{ hasMismatch ? '!' : pending.length ? '·' : '✓' }}</span>{{ hasMismatch ? 'Требует внимания' : pending.length ? 'Есть непроверенные данные' : 'Проверка завершена' }}</span><h3>{{ heroTitle }}</h3><p>{{ heroText }}</p><div class="report-context"><span v-if="project.verification_scope?.report_row">{{ project.verification_scope.report_row }}</span><span v-if="project.verification_scope?.period_start">{{ formatDate(project.verification_scope.period_start) }} — {{ formatDate(project.verification_scope.period_end) }}</span><span>{{ project.documents.length }} документов в комплекте</span></div></div><div v-if="headlineDifference !== null && headlineDifference !== undefined" class="verdict-amount"><span>{{ total?.status !== 'mismatch' ? 'Расхождение по статье' : Number(headlineDifference) >= 0 ? 'Завышение отчёта' : 'Занижение отчёта' }}</span><strong>{{ money(Math.abs(Number(headlineDifference))) }}</strong><small v-if="total?.status === 'mismatch'">Уже учтено в общем итоге</small></div></section>
      <div class="report-workspace"><div class="report-main">
        <div class="report-filters" role="group" aria-label="Фильтр показателей"><button v-for="tab in filters" :key="tab.id" :class="{ active: filter === tab.id }" :aria-pressed="filter === tab.id" @click="filter = tab.id">{{ tab.label }} <span>{{ tab.count }}</span></button></div>
        <div class="report-filter-heading"><h3>{{ filter === 'problems' ? 'Что нужно исправить' : filter === 'pending' ? 'Что пока не подтверждено' : filter === 'matched' ? 'Что подтверждено' : 'Все показатели отчёта' }}</h3><p v-if="filter === 'problems' && total?.status === 'mismatch'">Разница по статье отражается в общем итоге и учитывается один раз.</p><p v-else-if="filter === 'pending'">Недостаток данных не означает ошибку в отчёте.</p><p v-else-if="filter === 'matched'">Для каждой суммы можно открыть подтверждающий документ.</p></div>
        <div v-if="!visible.length" class="report-empty"><span aria-hidden="true">✓</span><h4>{{ filter === 'problems' ? 'Расхождений по статьям нет' : 'Здесь пока нет показателей' }}</h4><p>{{ filter === 'problems' && pending.length ? 'Посмотрите непроверенные данные, прежде чем принимать решение.' : 'Выберите другой фильтр, чтобы посмотреть результаты проверки.' }}</p><button v-if="filter === 'problems' && pending.length" class="review-button secondary" @click="filter='pending'">Посмотреть неподтверждённые</button></div>
        <article v-for="row in visible" :key="row.id" class="report-indicator" :class="row.status">
          <div class="indicator-heading"><div class="indicator-title"><span class="indicator-symbol" aria-hidden="true">{{ row.status === 'mismatch' ? '!' : row.status === 'matched' ? '✓' : '?' }}</span><h4>{{ row.title }}</h4></div><span class="indicator-state">{{ statusLabels[row.status] || 'Нужна проверка' }}</span></div>
          <p class="indicator-explanation">{{ rowExplanation(row) }}</p>
          <div class="indicator-values"><div><span>В отчёте</span><strong>{{ money(row.actual, row.currency || '') }}</strong><button v-if="row.actualSource?.document_id" class="inline-document" @click="open(row.actualSource)">Показать в отчёте ↗</button></div><div><span>Подтверждено документами</span><strong>{{ money(row.expected, row.currency || '') }}</strong><small v-if="row.expected === null || row.expected === undefined">Недостаточно данных</small><small v-else>{{ row.sources.length }} {{ row.sources.length === 1 ? 'источник' : row.sources.length < 5 ? 'источника' : 'источников' }}</small></div><div v-if="row.status === 'mismatch'" class="indicator-delta"><span>Разница</span><strong>{{ money(Math.abs(Number(row.difference)), row.currency || 'RUB') }}</strong></div></div>
          <div v-if="row.sources.length" class="indicator-evidence"><button class="evidence-toggle" :aria-expanded="evidenceOpen(row)" @click="toggle(row.id)"><AppIcon name="file" /><span>Подтверждающие документы</span><small>{{ row.sources.length }}</small><span class="evidence-chevron">{{ evidenceOpen(row) ? '−' : '+' }}</span></button><div v-if="evidenceOpen(row)" class="evidence-list"><button v-for="(source,index) in row.sources" :key="source.document_id + ':' + index" class="report-source-link" @click="open(source)"><span class="source-file-symbol"><AppIcon name="file" /></span><span class="source-file-copy"><b>{{ shortName(source.file_name) }}</b><small>{{ location(source) }}</small></span><span class="source-file-amount">{{ money(source.value, source.value?.currency || row.currency || '') }}</span><span aria-hidden="true" class="source-open-arrow">↗</span></button><div v-if="row.sources.length > 1" class="evidence-sum"><span>Итого по документам</span><b>{{ money(row.expected, row.currency || '') }}</b></div></div></div>
        </article>
        <section v-if="exclusions.length" class="report-exclusions"><header><div><h3>Исключены из расчёта</h3><p>Эти документы не увеличивают подтверждённую сумму.</p></div><span>{{ exclusions.length }}</span></header><div v-for="(item,index) in exclusions" :key="index" class="excluded-document"><span class="excluded-mark" aria-hidden="true">−</span><div><button class="excluded-document-title" @click="open(primarySource(item))">{{ shortName(item.file_name) }} ↗</button><p>{{ item.category === 'duplicate_operation' ? 'Повторяет уже учтённый документ. В расчёт включён один экземпляр.' : item.category === 'wrong_period' ? 'Дата документа выходит за выбранный период проверки.' : item.category === 'incorrect_document_link' ? 'Номер договора отличается от договора в отчёте.' : item.message }}</p></div><span class="exclusion-reason">{{ findingLabels[item.category] || 'Нужна проверка' }}</span></div></section>
      </div>
      <aside class="report-aside"><section class="report-total"><span class="aside-kicker">Общий итог</span><h3>Сводка по комплекту</h3><dl><div><dt>В отчёте</dt><dd>{{ money(total?.actual) }}</dd></div><div><dt>По документам</dt><dd>{{ money(total?.expected) }}</dd></div><div v-if="total?.difference !== null && total?.difference !== undefined" :class="{ 'total-difference': total?.status === 'mismatch' }"><dt>Разница</dt><dd>{{ money(Math.abs(Number(total?.difference))) }}</dd></div></dl><button v-if="total?.actualSource" class="inline-document" @click="open(total?.actualSource)">Открыть итог в отчёте ↗</button><p v-if="!total || total.status === 'insufficient_data'" class="total-note">Общий итог пока не подтверждён полностью.</p><div class="report-counts"><span><i class="count-dot green"></i>Совпадает<b>{{ matched.length }}</b></span><span><i class="count-dot red"></i>Расхождения<b>{{ problems.length }}</b></span><span><i class="count-dot amber"></i>Не подтверждено<b>{{ pending.length }}</b></span></div></section>
        <section class="report-decision" aria-labelledby="decision-heading"><span class="aside-kicker">Ваше решение</span><h3 id="decision-heading">Принять отчёт?</h3><p>Ознакомьтесь с расхождениями и подтверждениями. Решение сохранится для этой версии отчёта.</p><div v-if="decision" class="decision-saved" :class="{ rejected: decision.status === 'rejected', outdated: decision.outdated }"><strong>{{ decision.outdated ? 'Результат изменился' : decision.status === 'accepted' ? 'Отчёт принят' : 'Отчёт отклонён' }}</strong><span>{{ decision.outdated ? 'Предыдущее решение относится к другой версии. Проверьте обновлённый отчёт.' : formatDate(decision.decided_at) }}</span><p v-if="decision.comment && !decision.outdated">{{ decision.comment }}</p></div><label class="decision-comment">Комментарий <span>необязательно</span><textarea v-model="comment" maxlength="2000" rows="3" placeholder="Например, вернуть на исправление суммы по статье 0800" :disabled="saving || busy"></textarea></label><p v-if="decisionError" class="decision-error" role="alert">{{ decisionError }}</p><p v-if="savedNotice" class="decision-success" role="status">{{ savedNotice }}</p><div class="decision-actions"><button class="review-button accept" :disabled="saving || busy || project.status === 'running' || !project.report_fingerprint" @click="saveDecision('accepted')"><AppIcon name="check" />{{ saving ? 'Сохраняем…' : 'Принять отчёт' }}</button><button class="review-button reject" :disabled="saving || busy || project.status === 'running' || !project.report_fingerprint" @click="saveDecision('rejected')">Отклонить отчёт</button></div><small class="decision-footnote">Ваше решение сохраняется отдельно. Результаты проверки и найденные проблемы остаются в отчёте.</small></section>
      </aside></div>
    </template>
    <div v-else class="report-empty"><AppIcon name="result" /><h3>Результаты появятся после проверки</h3><p>{{ project.stages.verification?.error?.message || project.stages.reconciliation?.error?.message || 'Загрузите отчёт и первичные документы, затем запустите проверку комплекта.' }}</p></div>
    <ReportSourceDrawer :source="selectedSource" :project="project" @close="selectedSource = null" />
    <PdfReportViewer :project-id="project.id" :open="pdfOpen" @close="pdfOpen = false" />
  </section>
</template>

<style scoped>
.review-report{--r-ink:#243d31;--r-muted:#66776e;--r-line:#e1e6de;--r-green:#265f43;--r-red:#b14032;--r-amber:#92611c;color:var(--r-ink);padding-bottom:35px;min-width:0}.report-toolbar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:8px 0 25px}.report-overline,.aside-kicker{font-size:11px;font-weight:650;letter-spacing:.08em;text-transform:uppercase;color:var(--r-muted)}.report-toolbar h2{font-size:29px;letter-spacing:-.045em;margin:5px 0 0;font-weight:650;line-height:1.2}.report-tools{display:flex;align-items:center;gap:10px}.review-button{display:inline-flex;justify-content:center;align-items:center;gap:9px;border:1px solid transparent;border-radius:9px;padding:11px 16px;font:600 13px/1.4 inherit;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer;transition:background .18s,border-color .18s,transform .18s;min-height:43px}.review-button:active,.review-icon-button:active{transform:translateY(1px)}.review-button.secondary{background:#fff;border-color:#dce3da;color:#344b3d}.review-button.secondary:hover{background:#f2f6ee;border-color:#b6c8b6}.review-icon-button{height:43px;width:43px;border:1px solid #dce3da;border-radius:9px;background:#fff;font-size:23px;cursor:pointer}.review-button:disabled,.review-icon-button:disabled{opacity:.5;cursor:wait}.report-verdict{display:flex;align-items:center;justify-content:space-between;gap:30px;padding:27px 30px;background:#fffaf0;border:1px solid #eadfc7;border-radius:14px;margin-bottom:27px;position:relative;overflow:hidden}.report-verdict.has-problems{background:#fff7f3;border-color:#eddbd1}.report-verdict.all-clear{background:#f0f7ed;border-color:#d6e6cd}.verdict-main{max-width:640px}.verdict-status{display:flex;gap:8px;align-items:center;font-size:12px;font-weight:600;color:var(--r-amber)}.has-problems .verdict-status{color:var(--r-red)}.all-clear .verdict-status{color:var(--r-green)}.verdict-status>span{width:18px;height:18px;display:inline-grid;place-items:center;border:1px soli